// 原责任先行；仅本人已收申请能生成此计划，远方只回原首府，真正答复仍当地重报价。
#include "political_office_resignation_director.hpp"
#include "resident/domains/director/director_livelihood.hpp"
#include "resident/kernel/command_types.hpp"
namespace hanmo::resident {
Outcome<std::optional<DecisionProposal>> propose_director_office_resignation_response(const PoliticalOfficeResignationResponseDirectorContext& x,const KnownSubjectView& known,const DirectorPolicy& policy,const PoliticalOfficeResignationResponseIntent& i,const DecisionProposal& base,Integer limit){
 if(x.resignations.version!=2||!base.transition||base.subject_id!=known.actor_id||known.subject.kind!=SubjectKind::actor||known.subject.id!=known.actor_id||known.tick!=x.common.tick()||known.revision!=x.common.revision()||base.transition->expected_revision!=known.revision||limit<1||limit>64)return {false,{},common_failure("InvalidOfficeResignationResponseProposal",known.actor_id,ErrorKind::internal).error};
 if(base.command||base.transition->current_action_id||!known.commitments.empty()||!base.transition->commitment_ids.empty()||base.transition->template_id=="maintain_commitment"||known.actor_id==x.common.state().metadata.player_actor_id||known.actor_id!=i.approver_actor_id||!known.alive||!known.available||!known.current_action_id.empty()||known.interaction_busy)return {true,std::nullopt,{}};
 const auto* p=x.resignations.policies.find(i.resignation_policy_id);const auto* h=p?x.heads.policies.find(p->approval_succession_policy_id):nullptr;if(!h||x.selected_policy_id!=i.director_policy_id||policy.organization_id!=h->organization_id)return {false,{},common_failure("OfficeResignationResponseDirectorPolicyMismatch",i.id).error};
 auto source=x.read.known_response(known.actor_id,i);if(!source.ok)return {false,{},source.error};const auto& k=source.value;const auto& a=k.identity;const auto& b=x.common.state().identity;if(k.observer_actor_id!=known.actor_id||k.intent_id!=i.id||std::tie(a.world_id,a.execution_epoch,a.revision,a.tick)!=std::tie(b.world_id,b.execution_epoch,b.revision,b.tick))return {false,{},common_failure("OfficeResignationResponseKnowledgeMismatch",i.id).error};if(k.request_fact_id.empty())return {true,std::nullopt,{}};
 auto out=base;auto t=std::make_shared<DirectorTransition>(*base.transition);out.transition=t;t->template_id=political_office_resignation_response_template;t->goal_ref=k.request_fact_id;t->phase=PlanPhase::waiting;t->current_action_id.reset();t->next_step_index=0;t->wait_reason.clear();t->livelihood.reset();t->pending_life_action_id.reset();t->last_life_fact_id.reset();out.reason_fact_id=k.request_fact_id;
 if(!k.own_answer_fact_id.empty()){if(base.transition->template_id==political_office_resignation_response_template&&base.transition->phase==PlanPhase::completed&&base.transition->goal_ref==k.own_answer_fact_id)return {true,std::nullopt,{}};t->phase=PlanPhase::completed;t->goal_ref=k.own_answer_fact_id;out.reason_fact_id=k.own_answer_fact_id;return {true,std::move(out),{}};}
 if(x.common.tick()>=k.response_until){t->wait_reason="PoliticalOfficeResignationClosed";return {true,std::move(out),{}};}
 if(known.place_id!=h->seat_place_id){out.command=director_move_toward(x.travel,known,h->seat_place_id);t->phase=out.command?PlanPhase::delivering:PlanPhase::waiting;t->wait_reason=out.command?StableId{}:"OfficeResignationResponseRouteUnavailable";return {true,std::move(out),{}};}
 auto q=x.read.preview_response_local(known.actor_id,i,k);if(!q.ok){if(q.error.kind!=ErrorKind::rule)return {false,{},q.error};t->wait_reason=q.error.original.code;return {true,std::move(out),{}};}if(!q.value||q.value->kind!=political_office_resignation_answer_command)return {false,{},common_failure("OfficeResignationResponseCommandRequired",i.id,ErrorKind::internal).error};out.command=std::move(q.value);t->phase=PlanPhase::accepting;return {true,std::move(out),{}};
}
}
